    "diagramSvgUrdu": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 720 390\" role=\"img\" aria-label=\"Figure 14.11: one-cycle coil positions and alternating induced e.m.f.\" style=\"width:100%;max-width:720px;height:auto\"><rect width=\"100%\" height=\"100%\" fill=\"#fff\"/><path d=\"M85 195H660M100 60V330\" stroke=\"#334155\" stroke-width=\"2\"/><path d=\"M105 195C170 80 230 80 295 195S420 310 485 195S610 80 655 195\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"5\"/><path d=\"M120 195H645\" stroke=\"#64748b\" stroke-width=\"2\" stroke-dasharray=\"8 8\"/><circle cx=\"120\" cy=\"195\" r=\"7\" fill=\"#dc2626\"/><text x=\"95\" y=\"350\">0°</text><circle cx=\"250\" cy=\"92\" r=\"7\" fill=\"#dc2626\"/><text x=\"225\" y=\"350\">90°</text><circle cx=\"380\" cy=\"195\" r=\"7\" fill=\"#dc2626\"/><text x=\"355\" y=\"350\">180°</text><circle cx=\"510\" cy=\"298\" r=\"7\" fill=\"#dc2626\"/><text x=\"485\" y=\"350\">270°</text><circle cx=\"640\" cy=\"195\" r=\"7\" fill=\"#dc2626\"/><text x=\"615\" y=\"350\">360°</text><text x=\"250\" y=\"35\">کوائل کی حالت اور القائی e.m.f.</text><text x=\"620\" y=\"220\">t</text><text x=\"105\" y=\"50\">ε</text></svg>",
    "diagramSvgPashto": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 720 390\" role=\"img\" aria-label=\"Figure 14.11: one-cycle coil positions and alternating induced e.m.f.\" style=\"width:100%;max-width:720px;height:auto\"><rect width=\"100%\" height=\"100%\" fill=\"#fff\"/><path d=\"M85 195H660M100 60V330\" stroke=\"#334155\" stroke-width=\"2\"/><path d=\"M105 195C170 80 230 80 295 195S420 310 485 195S610 80 655 195\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"5\"/><path d=\"M120 195H645\" stroke=\"#64748b\" stroke-width=\"2\" stroke-dasharray=\"8 8\"/><circle cx=\"120\" cy=\"195\" r=\"7\" fill=\"#dc2626\"/><text x=\"95\" y=\"350\">0°</text><circle cx=\"250\" cy=\"92\" r=\"7\" fill=\"#dc2626\"/><text x=\"225\" y=\"350\">90°</text><circle cx=\"380\" cy=\"195\" r=\"7\" fill=\"#dc2626\"/><text x=\"355\" y=\"350\">180°</text><circle cx=\"510\" cy=\"298\" r=\"7\" fill=\"#dc2626\"/><text x=\"485\" y=\"350\">270°</text><circle cx=\"640\" cy=\"195\" r=\"7\" fill=\"#dc2626\"/><text x=\"615\" y=\"350\">360°</text><text x=\"250\" y=\"35\">د کویل حالت او القاشوې e.m.f.</text><text x=\"620\" y=\"220\">t</text><text x=\"105\" y=\"50\">ε</text></svg>"
