    "diagramSvgUrdu": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 400\" role=\"img\" aria-label=\"R-C series circuit and phasor diagram\" style=\"width:100%;max-width:600px;height:auto\"><rect width=\"100%\" height=\"100%\" fill=\"#fff\"/><path d=\"M90 80H520V270H90V80\" fill=\"none\" stroke=\"#334155\" stroke-width=\"4\"/><circle cx=\"90\" cy=\"175\" r=\"32\" fill=\"white\" stroke=\"#2563eb\" stroke-width=\"4\"/><path d=\"M70 175q10-20 20 0t20 0\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"3\"/><path d=\"M470 125l18 18-18 18 18 18-18 18 18 18\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"4\"/><path d=\"M475 215v55m20-55v55\" stroke=\"#111827\" stroke-width=\"5\"/><path d=\"M160 345H410\" stroke=\"#2563eb\" stroke-width=\"4\"/><path d=\"M160 345V215\" stroke=\"#dc2626\" stroke-width=\"4\"/><path d=\"M160 215H410\" stroke=\"#16a34a\" stroke-width=\"4\"/><path d=\"M160 345L410 215\" stroke=\"#7c3aed\" stroke-width=\"4\"/><path d=\"M145 345a40 40 0 0 1 22-37\" fill=\"none\" stroke=\"#111827\" stroke-width=\"2\"/><text x=\"30\" y=\"60\">اے سی منبع</text><text x=\"515\" y=\"165\">مزاحمت R</text><text x=\"515\" y=\"300\">کپیسٹر C</text><text x=\"410\" y=\"335\">رو I</text><text x=\"265\" y=\"365\">V_R</text><text x=\"145\" y=\"200\">V_C</text><text x=\"180\" y=\"315\">90°</text></svg>",
    "diagramSvgPashto": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 400\" role=\"img\" aria-label=\"R-C series circuit and phasor diagram\" style=\"width:100%;max-width:600px;height:auto\"><rect width=\"100%\" height=\"100%\" fill=\"#fff\"/><path d=\"M90 80H520V270H90V80\" fill=\"none\" stroke=\"#334155\" stroke-width=\"4\"/><circle cx=\"90\" cy=\"175\" r=\"32\" fill=\"white\" stroke=\"#2563eb\" stroke-width=\"4\"/><path d=\"M70 175q10-20 20 0t20 0\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"3\"/><path d=\"M470 125l18 18-18 18 18 18-18 18 18 18\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"4\"/><path d=\"M475 215v55m20-55v55\" stroke=\"#111827\" stroke-width=\"5\"/><path d=\"M160 345H410\" stroke=\"#2563eb\" stroke-width=\"4\"/><path d=\"M160 345V215\" stroke=\"#dc2626\" stroke-width=\"4\"/><path d=\"M160 215H410\" stroke=\"#16a34a\" stroke-width=\"4\"/><path d=\"M160 345L410 215\" stroke=\"#7c3aed\" stroke-width=\"4\"/><path d=\"M145 345a40 40 0 0 1 22-37\" fill=\"none\" stroke=\"#111827\" stroke-width=\"2\"/><text x=\"30\" y=\"60\">A.C. سرچینه</text><text x=\"515\" y=\"165\">مقاومت R</text><text x=\"515\" y=\"300\">کپیسیټر C</text><text x=\"410\" y=\"335\">جریان I</text><text x=\"265\" y=\"365\">V_R</text><text x=\"145\" y=\"200\">V_C</text><text x=\"180\" y=\"315\">90°</text></svg>"
