    "diagramSvgUrdu": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 700 480\" role=\"img\" aria-label=\"Electromagnetic radiation and ECG waveform\" style=\"width:100%;max-width:700px;height:auto\"><rect width=\"100%\" height=\"100%\" fill=\"#fff\"/><path d=\"M55 280H660M55 280V90\" stroke=\"#334155\" stroke-width=\"3\"/><path d=\"M70 270L160 260L205 275L245 225L270 90L295 305L345 270L420 255L470 270L520 235L560 255L650 265\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"4\"/><path d=\"M90 90H640\" stroke=\"#64748b\" stroke-dasharray=\"5 5\"/><path d=\"M100 420H600\" stroke=\"#334155\" stroke-width=\"2\"/><path d=\"M120 420V365M160 420V365M200 420V365M240 420V365M280 420V365M320 420V365\" stroke=\"#7c3aed\" stroke-width=\"5\"/><rect x=\"110\" y=\"345\" width=\"150\" height=\"95\" fill=\"none\" stroke=\"#111827\" stroke-width=\"2\"/><path d=\"M350 370h220v50H350z\" fill=\"#e0f2fe\" stroke=\"#0284c7\" stroke-width=\"2\"/><text x=\"65\" y=\"65\">بالائے بنفشی</text><text x=\"175\" y=\"65\">ایکس رے</text><text x=\"290\" y=\"65\">گاما رے</text><text x=\"205\" y=\"215\">P</text><text x=\"225\" y=\"320\">Q</text><text x=\"265\" y=\"75\">R</text><text x=\"295\" y=\"340\">S</text><text x=\"520\" y=\"225\">T</text><text x=\"560\" y=\"450\">وقت</text><text x=\"370\" y=\"400\">ای سی جی وولٹیج</text></svg>",
    "diagramSvgPashto": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 700 480\" role=\"img\" aria-label=\"Electromagnetic radiation and ECG waveform\" style=\"width:100%;max-width:700px;height:auto\"><rect width=\"100%\" height=\"100%\" fill=\"#fff\"/><path d=\"M55 280H660M55 280V90\" stroke=\"#334155\" stroke-width=\"3\"/><path d=\"M70 270L160 260L205 275L245 225L270 90L295 305L345 270L420 255L470 270L520 235L560 255L650 265\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"4\"/><path d=\"M90 90H640\" stroke=\"#64748b\" stroke-dasharray=\"5 5\"/><path d=\"M100 420H600\" stroke=\"#334155\" stroke-width=\"2\"/><path d=\"M120 420V365M160 420V365M200 420V365M240 420V365M280 420V365M320 420V365\" stroke=\"#7c3aed\" stroke-width=\"5\"/><rect x=\"110\" y=\"345\" width=\"150\" height=\"95\" fill=\"none\" stroke=\"#111827\" stroke-width=\"2\"/><path d=\"M350 370h220v50H350z\" fill=\"#e0f2fe\" stroke=\"#0284c7\" stroke-width=\"2\"/><text x=\"65\" y=\"65\">الټراوایلیټ</text><text x=\"175\" y=\"65\">ایکس وړانګې</text><text x=\"290\" y=\"65\">ګاما وړانګې</text><text x=\"205\" y=\"215\">P</text><text x=\"225\" y=\"320\">Q</text><text x=\"265\" y=\"75\">R</text><text x=\"295\" y=\"340\">S</text><text x=\"520\" y=\"225\">T</text><text x=\"560\" y=\"450\">وخت</text><text x=\"370\" y=\"400\">ECG ولتاژ</text></svg>"
