{ const items = PHYS_12_DATA[0].workedExamples; const entry = {"id": "textbook-example-1", "num": "11.1", "title": "Example 11.1", "problem": "Three charges \\(q_1=-5\\,\\mu\\mathrm C\\), \\(q_2=+10\\,\\mu\\mathrm C\\) and \\(q_3=-12\\,\\mu\\mathrm C\\) are placed in a line as shown in figure. Calculate the net electrostatic force on charge \\(q_2\\) due to the other two charges.", "given": ["Charge \\(q_1=-5\\,\\mu\\mathrm C=-5\\times10^{-6}\\,\\mathrm C\\)", "Charge \\(q_2=+10\\,\\mu\\mathrm C=+10\\times10^{-6}\\,\\mathrm C\\)", "Charge \\(q_3=-12\\,\\mu\\mathrm C=-12\\times10^{-6}\\,\\mathrm C\\)", "\\(k=9\\times10^9\\;\\mathrm{N\\,m^2\\,C^{-2}}\\)", "The distance between charge \\(q_1\\) and \\(q_2\\): \\(r_{12}=6\\,\\mathrm{cm}=0.06\\,\\mathrm m=6\\times10^{-2}\\,\\mathrm m\\)", "The distance between charge \\(q_2\\) and \\(q_3\\): \\(r_{23}=4\\,\\mathrm{cm}=0.04\\,\\mathrm m=4\\times10^{-2}\\,\\mathrm m\\)"], "steps": ["Electrostatic force on charge \\(q_2\\) due to charge \\(q_1\\): \\(F_{21}=k\\frac{q_1q_2}{r_{12}^2}\\)", "\\(F_{21}=9.0\\times10^9\\;\\mathrm{N\\,m^2\\,C^{-2}}\\frac{(5\\times10^{-6}\\,\\mathrm C)(10\\times10^{-6}\\,\\mathrm C)}{(6\\times10^{-2}\\,\\mathrm m)^2}\\)", "\\(=9.0\\times10^9\\;\\mathrm{N\\,m^2\\,C^{-2}}\\frac{50\\times10^{-12}\\,\\mathrm{C^2}}{36\\times10^{-4}\\,\\mathrm{m^2}}=125\\,\\mathrm N\\)", "Electrostatic force on charge \\(q_2\\) due to \\(q_3\\):", "\\(F_{23}=9.0\\times10^9\\;\\mathrm{N\\,m^2\\,C^{-2}}\\frac{(10\\times10^{-6}\\,\\mathrm C)(12\\times10^{-6}\\,\\mathrm C)}{4\\times10^{-2}\\,\\mathrm m}\\)", "\\(=9.0\\times10^9\\;\\mathrm{N\\,m^2\\,C^{-2}}\\frac{120\\times10^{-12}\\,\\mathrm{C^2}}{16\\times10^{-4}\\,\\mathrm{m^2}}\\)", "\\(=\\frac{1080\\times10^{-3}}{16\\times10^{-4}}\\,\\mathrm N=675\\,\\mathrm N\\)", "The net electrostatic force on charge \\(q_2\\), printed as \\(F_2=F_{21}-F_{23}\\):", "\\(675\\,\\mathrm N-125\\,\\mathrm N=550\\,\\mathrm N\\)", "The direction of the net electrostatic force on charge \\(q_2\\) points towards charge \\(q_3\\) (points to the right)."], "answer": "550 N towards q₃ (to the right)", "solutionOrigin": "textbook", "sourceReferences": [{"pdfPage": 8, "printedPage": 6}, {"pdfPage": 8, "printedPage": 7}], "sourceClarifications": ["Source clarification: the first printed substitution for \\(F_{23}\\) omits the square on the distance; the next line correctly uses \\(16\\times10^{-4}\\,\\mathrm{m^2}\\). The printed net-force labels are reversed relative to the subtraction \\(675-125\\). Taking right as positive gives \\(F_2=F_{23}-F_{21}=+550\\,\\mathrm N\\). The original printed statements are retained above; these are textbook typographical inconsistencies."], "diagramSvg": "<svg viewBox=\"0 0 520 125\" role=\"img\" aria-label=\"Three collinear point charges\" style=\"width:100%;max-width:560px\"><defs><marker id=\"phys12-example111\" markerWidth=\"8\" markerHeight=\"8\" refX=\"4\" refY=\"4\" orient=\"auto-start-reverse\"><path d=\"M0 0L8 4L0 8Z\" fill=\"#334155\"/></marker></defs><circle cx=\"65\" cy=\"70\" r=\"18\" fill=\"#cffafe\" stroke=\"#334155\"/><text x=\"59\" y=\"76\" font-size=\"20\">−</text><text x=\"55\" y=\"35\">q1</text><circle cx=\"245\" cy=\"70\" r=\"18\" fill=\"#f9a8d4\" stroke=\"#334155\"/><text x=\"239\" y=\"76\" font-size=\"20\">+</text><text x=\"235\" y=\"35\">q2</text><circle cx=\"445\" cy=\"70\" r=\"18\" fill=\"#cffafe\" stroke=\"#334155\"/><text x=\"439\" y=\"76\" font-size=\"20\">−</text><text x=\"435\" y=\"35\">q3</text><line x1=\"85\" y1=\"70\" x2=\"225\" y2=\"70\" stroke=\"#334155\" marker-start=\"url(#phys12-example111)\" marker-end=\"url(#phys12-example111)\"/><text x=\"139\" y=\"55\">6 cm</text><line x1=\"265\" y1=\"70\" x2=\"425\" y2=\"70\" stroke=\"#334155\" marker-start=\"url(#phys12-example111)\" marker-end=\"url(#phys12-example111)\"/><text x=\"329\" y=\"55\">4 cm</text></svg>"}; const index = items.findIndex(item => item.id === entry.id); if (index >= 0) items[index] = entry; else items.push(entry); }
